B=len(c); ct=torch.tensor(c)
def run(delta,K=9,thr=0.0):
    x=xi.clone(); fired=torch.zeros(B,dtype=torch.bool)
    for k in range(20):
        t=torch.full((B,),1-k/20)
        v,A=net.velocity(x,t,ct,("blocks.1",),count=False)
        if k<K:
            f=(A["blocks.1"]@w+b)>thr; fired|=f
            v=v+f[:,None].float()*torch.tensor(delta,dtype=torch.float32)
        x=x-v/20
    return x.numpy(),fired.numpy()
with torch.no_grad():
    _,f0=run(np.zeros(2))
    ang=np.degrees(np.arctan2(a0[:,1],a0[:,0])); lab=f0&(np.abs(ang-(-75+45*c))<25)
    feat=lambda a: np.c_[a, c*6]; tree=cKDTree(feat(a0))
    def tgt(a):
        _,idx=tree.query(feat(a),k=10); return lab[idx].mean(1)>0.5
    def hist(a,m):
        an=np.degrees(np.arctan2(a[m,1],a[m,0])); h=[]
        for lo in np.arange(0,1,0.2):
            mm=(c[m]>=lo)&(c[m]<lo+0.2); hh,_=np.histogram(an[mm],bins=24,range=(-180,180)); h.append(hh)
        return np.concatenate(h)
    h0=hist(a0,~lab); r0=np.linalg.norm(a0,axis=1)
    for K in [9,13]:
     for thr in [0,-3]:
