       for j in [5,5.5,6,0]:
        th=np.radians(45*j); d=mag*np.array([np.cos(th),np.sin(th)])
        a1,f=run(d,K,thr); T=tgt(a1)
        h1=hist(a1,~T); tv=0.5*np.abs(h1/h1.sum()-h0/h0.sum()).sum()
        moved=(np.linalg.norm(a1-a0,axis=1)>0.3)&~lab
        r1=np.linalg.norm(a1,axis=1); off=((r1<2.2)|(r1>3.8)).mean()-((r0<2.2)|(r0>3.8)).mean()
        print(K,thr,mag,j,'tgt',round(T.mean(),3),'tv',round(tv,3),'ntmoved',round(moved.mean(),3),'offring',round(off,3))

